# Test hypothesis: the "shared" value is output when mismatched
G = load_grids()

def apply_rule(input_grid, divider_col):
    # Get dimensions
    h = len(input_grid)
    w = len(input_grid[0])

    # Extract left and right sections
    left = [row[:divider_col] for row in input_grid]
    right = [row[divider_col+1:] for row in input_grid]

    # Find "shared" color (not 6, appears in both)
    left_vals = set()
    right_vals = set()
    for row in input_grid:
        for c in range(divider_col):
            left_vals.add(row[c])
        for c in range(divider_col+1, w):
            right_vals.add(row[c])

    # Shared (excluding 6)
    shared = (left_vals & right_vals) - {6}
    if not shared:
        shared = left_vals & right_vals  # fallback

    # Apply transformation
    output = []
    for r in range(h):
        row_out = []
        for c in range(len(left[r])):
            l = left[r][c]
            rr = right[r][c]
            if l == rr:
                row_out.append(3)
            else:
                row_out.append(int(shared[0]))  # Shared value is output
        output.append(row_out)

    return output

